# Disable Windows UI Animations Write-Host "Disabling Windows UI animations..." -ForegroundColor Cyan # Disable visual animations Set-ItemProperty -Path "HKCU:\Control Panel\Desktop" -Name "UserPreferencesMask" -Value ([byte[]](0x90,0x12,0x03,0x80,0x10,0x00,0x00,0x00)) -Type Binary -Force -ErrorAction SilentlyContinue # Disable window animation Set-ItemProperty -Path "HKCU:\Control Panel\Desktop\WindowMetrics" -Name "MinAnimate" -Value "0" -Force -ErrorAction SilentlyContinue # Disable taskbar animations Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "TaskbarAnimations" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue # Disable tooltip slide/fade Set-ItemProperty -Path "HKCU:\Control Panel\Desktop" -Name "SmoothScroll" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue # Disable listview animation Set-ItemProperty -Path "HKCU:\Control Panel\Desktop" -Name "ListviewShadow" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue # Disable drag full windows Set-ItemProperty -Path "HKCU:\Control Panel\Desktop" -Name "DragFullWindows" -Value "0" -Force -ErrorAction SilentlyContinue Write-Host "Windows UI animations have been disabled." -ForegroundColor Green Write-Host "Sign out and sign back in for all changes to take effect." -ForegroundColor Yellow